+    data.qStrideGroup = heads * DIM;
+    data.qStrideHead = DIM;
+    data.weightStrideToken = groups * heads;
+    data.weightStrideGroup = heads;
+    data.cacheStrideRegion = DIM;
+    data.blockTableStrideRequest = data.pageCols;
