+    GlobalTensor<float> weightsFp32Gm_;
+    GlobalTensor<bfloat16_t> weightsBf16Gm_;
+    GlobalTensor<half> weightsFp16Gm_;
+    GlobalTensor<int32_t> actualKvLengthsGm_;
+    GlobalTensor<float> outputGm_;
+
